sited.script:

// 核心的「內容列表」解析函式
function list_parse(url, jsontext) {
    // 1. 將傳入的 JSON 字串轉換為 JavaScript 物件
    const data = JSON.parse(jsontext);

    // 2. 檢查 'items' 屬性是否存在且為一個陣列
    if (!data || !Array.isArray(data.items)) {
        // 如果資料結構不符，回傳一個空的 JSON 陣列字串
        return JSON.stringify([]);
    }

    const list = data.items.map(item => {
        return {
            logo: 'https://static.ttkan.co/cover/' + item.topic_img,
            name: item.name,
            url: 'https://www.ttkan.co/novel/chapters/' + item.novel_id
        };
    });

    return JSON.stringify(list);
}

function book_parse_api_response(url, html) {
    var $ = cheerio.load(html);
    var sections = [];
    $(".full_chapters a").each(function(){
        if ($(this).attr("href").match(/https/)) sections.push({name: $(this).text(), url: $(this).attr("href")});
    });
    var book = {
        name: gbk2big5.traditionalized($("h1.booktitle").text().trim()),
        sections: sections
    };
    return JSON.stringify(book);
}

function section_parse(url, html) {
    var $ = cheerio.load(html);
    var data = [];
    $("h1").each(function(){
        data.push({t: "text", d: $(this).text().trim(), b:1, a:"center", s:2});
    });
    $(".content p").each(function(){
        data.push({t: "text", d: $(this).text().trim()});
    });
    return JSON.stringify({type:"article", data: data});
}
